package com.exchangepro.marketdata;

/**
 * Source of market prices shown to users.
 *
 * <ul>
 *   <li>{@link #SIMULATION} - synthetic prices generated by the platform. Always labelled "SIMULATED DATA".</li>
 *   <li>{@link #REAL} - a licensed external provider. Disabled until a provider whose terms permit free,
 *       multi-user display is integrated. The application never claims a live NSE/BSE connection.</li>
 * </ul>
 */
public enum MarketDataMode {
    SIMULATION("SIMULATED DATA"),
    REAL("REAL MARKET DATA");

    private final String displayLabel;

    MarketDataMode(String displayLabel) {
        this.displayLabel = displayLabel;
    }

    public String displayLabel() {
        return displayLabel;
    }
}
